{"command":"cd /workspace && cat > log.go <<'EOF'
package main

import (
	"fmt"
	"os"
	"strings"
	"sync"
	"time"
)

type logLevel int

const (
	levelError logLevel = iota
	levelWarn
	levelInfo
	levelDebug
)

var (
	currentLogLevel = levelInfo
	logMutex        sync.Mutex
)

func logLine(level logLevel, msg string) {
	if level > currentLogLevel {
		return
	}
	var tag string
	switch level {
	case levelError:
		tag = "[ERROR] "
	case levelWarn:
		tag = "[WARN]  "
	case levelInfo:
		tag = "[INFO]  "
	case levelDebug:
		tag = "[DEBUG] "
	}
	msg = strings.TrimRight(msg, "\n")
	ts := time.Now().Format("2006-01-02 15:04:05")
	logMutex.Lock()
	fmt.Fprintf(os.Stderr, "%s %s%s\n", ts, tag, msg)
	logMutex.Unlock()
}

func logErrorf(format string, a ...interface{}) { logLine(levelError, fmt.Sprintf(format, a...)) }
func logWarnf(format string, a ...interface{})  { logLine(levelWarn, fmt.Sprintf(format, a...)) }
func logInfof(format string, a ...interface{})  { logLine(levelInfo, fmt.Sprintf(format, a...)) }
func logDebugf(format string, a ...interface{}) { logLine(levelDebug, fmt.Sprintf(format, a...)) }
func logError(msg string)                       { logLine(levelError, msg) }
func logWarn(msg string)                        { logLine(levelWarn, msg) }
func logInfo(msg string)                        { logLine(levelInfo, msg) }
func logDebug(msg string)                       { logLine(levelDebug, msg) }
EOF"}

