{"command":"cd /workspace && cat > options.go <<'EOF'
package main

import (
	"fmt"
	"sort"
	"strings"
)

type OptionType int

const (
	OptionTypeString OptionType = iota
	OptionTypeBool
)

// Option represents a single configuration option.
type Option struct {
	Name         string
	Shorthand    byte
	Type         OptionType
	Default      string
	Description  string
	RequireValue bool
	HiddenOnCLI  bool
	Group        string
	EnumValues   []string
	HelpDefault  string // overrides default display in help, if non-empty
}

func StringOption(name string, shorthand byte, defaultValue, description string) *Option {
	return &Option{
		Name:         name,
		Shorthand:    shorthand,
		Type:         OptionTypeString,
		Default:      defaultValue,
		Description:  description,
		RequireValue: true,
	}
}

func BoolOption(name string, shorthand byte, defaultValue bool, description string) *Option {
	def := ""
	if defaultValue {
		def = "1"
	}
	return &Option{
		Name:        name,
		Shorthand:   shorthand,
		Type:        OptionTypeBool,
		Default:     def,
		Description: description,
	}
}

func (o *Option) ValueOptional() *Option {
	o.RequireValue = false
	return o
}

func (o *Option) Hidden() *Option {
	o.HiddenOnCLI = true
	return o
}

func (o *Option) Enum(values ...string) *Option {
	o.EnumValues = values
	return o
}

func (o *Option) HelpDef(d string) *Option {
	o.HelpDefault = d
	return o
}

// usageName returns the left column for help output, e.g. "--foo value"
func (o *Option) usageName() string {
	if o.Type == OptionTypeBool {
		if o.Default != "" {
			return "--[skip-]" + o.Name
		}
		return "--" + o.Name
	}
	if !o.RequireValue {
		return "--" + o.Name + "[=value]"
	}
	return "--" + o.Name + " value"
}

func (o *Option) usageDescription() string {
	desc := o.Description
	if len(o.EnumValues) > 0 {
		quoted := make([]string, len(o.EnumValues))
		for i, v := range o.EnumValues {
			quoted[i] = fmt.Sprintf("%q", v)
		}
		desc += " (valid values: " + strings.Join(quoted, ", ") + ")"
	}
	if o.Type == OptionTypeBool {
		if o.Default != "" {
			desc += fmt.Sprintf(" (enabled by default; disable with --skip-%s)", o.Name)
		}
	} else if o.HelpDefault != "" {
		desc += fmt.Sprintf(" (default %q)", o.HelpDefault)
	} else if o.Default != "" {
		desc += fmt.Sprintf(" (default %q)", o.Default)
	}
	return desc
}

// BoolValue converts a string to a boolean the same way option values are
// interpreted.
func BoolValue(input string) bool {
	switch strings.ToLower(input) {
	case "", "0", "false", "off":
		return false
	}
	return true
}

// NormalizeOptionName lowercases and converts underscores to dashes.
func NormalizeOptionName(name string) string {
	return strings.Replace(strings.ToLower(name), "_", "-", -1)
}

type ArgSpec struct {
	Name     string
	Default  string
	Required bool
}

// Command represents a command or the root command suite.
type Command struct {
	Name          string
	Summary       string
	Description   string
	DocURL        string
	options       map[string]*Option
	optionOrder   []*Option
	groupOrder    []string
	Handler       func(*Config) error
	SubCommands   map[string]*Command
	ParentCommand *Command
	args          []ArgSpec
	IsSuite       bool
}

func NewCommand(name, summary, description string, handler func(*Config) error) *Command {
	return &Command{
		Name:        name,
		Summary:     summary,
		Description: description,
		options:     make(map[string]*Option),
		Handler:     handler,
		SubCommands: make(map[string]*Command),
	}
}

func NewCommandSuite(name, summary, description string) *Command {
	cmd := NewCommand(name, summary, description, nil)
	cmd.IsSuite = true
	return cmd
}

func (cmd *Command) AddOption(opt *Option) {
	cmd.options[opt.Name] = opt
	cmd.optionOrder = append(cmd.optionOrder, opt)
	if opt.Group != "" {
		found := false
		for _, g := range cmd.groupOrder {
			if g == opt.Group {
				found = true
				break
			}
		}
		if !found {
			cmd.groupOrder = append(cmd.groupOrder, opt.Group)
		}
	}
}

func (cmd *Command) AddOptions(group string, opts ...*Option) {
	for _, opt := range opts {
		opt.Group = group
		cmd.AddOption(opt)
	}
}

func (cmd *Command) AddArg(name, def string, required bool) {
	cmd.args = append(cmd.args, ArgSpec{Name: name, Default: def, Required: required})
}

func (cmd *Command) AddSubCommand(sub *Command) {
	sub.ParentCommand = cmd
	cmd.SubCommands[sub.Name] = sub
}

func (cmd *Command) Root() *Command {
	c := cmd
	for c.ParentCommand != nil {
		c = c.ParentCommand
	}
	return c
}

// Options returns all options for this command, including inherited ones.
func (cmd *Command) Options() map[string]*Option {
	result := make(map[string]*Option)
	if cmd.ParentCommand != nil {
		for k, v := range cmd.ParentCommand.Options() {
			result[k] = v
		}
	}
	for k, v := range cmd.options {
		result[k] = v
	}
	return result
}

func (cmd *Command) OptionByShorthand(c byte) *Option {
	for _, opt := range cmd.Options() {
		if opt.Shorthand == c && c != 0 {
			return opt
		}
	}
	return nil
}

func (cmd *Command) MinArgs() int {
	n := 0
	for _, a := range cmd.args {
		if a.Required {
			n++
		}
	}
	return n
}

func (cmd *Command) MaxArgs() int {
	return len(cmd.args)
}

func (cmd *Command) sortedSubCommandNames() []string {
	names := make([]string, 0, len(cmd.SubCommands))
	for name := range cmd.SubCommands {
		names = append(names, name)
	}
	sort.Strings(names)
	return names
}

// allSuiteOptions returns every option known by any command in the suite.
func (cmd *Command) allSuiteOptions() map[string]*Option {
	root := cmd.Root()
	result := make(map[string]*Option)
	var walk func(c *Command)
	walk = func(c *Command) {
		for k, v := range c.options {
			if _, ok := result[k]; !ok {
				result[k] = v
			}
		}
		for _, name := range c.sortedSubCommandNames() {
			walk(c.SubCommands[name])
		}
	}
	walk(root)
	return result
}
EOF"}

