{"command":"cd /workspace && cat > config.go <<'EOF'
package main

import (
	"fmt"
	"regexp"
	"strconv"
	"strings"
	"unicode"
)

// OptionValuer is a source of option values.
type OptionValuer interface {
	OptionValue(name string) (string, bool)
	SourceName() string
}

// CommandLine represents parsed command-line state.
type CommandLine struct {
	InvokedAs    string
	Command      *Command
	OptionValues map[string]string
	ArgValues    []string
}

func (cli *CommandLine) OptionValue(name string) (string, bool) {
	v, ok := cli.OptionValues[name]
	return v, ok
}

func (cli *CommandLine) SourceName() string {
	return "command line"
}

// Config combines option values from multiple sources.
type Config struct {
	CLI     *CommandLine
	sources []OptionValuer // lowest priority first (excluding CLI)
}

func NewConfig(cli *CommandLine, sources ...OptionValuer) *Config {
	return &Config{CLI: cli, sources: sources}
}

func (cfg *Config) Clone() *Config {
	srcs := make([]OptionValuer, len(cfg.sources))
	copy(srcs, cfg.sources)
	return &Config{CLI: cfg.CLI, sources: srcs}
}

func (cfg *Config) AddSource(src OptionValuer) {
	cfg.sources = append(cfg.sources, src)
}

func (cfg *Config) FindOption(name string) *Option {
	return cfg.CLI.Command.Options()[name]
}

// lookup returns the value and supplier of an option, or the default.
func (cfg *Config) lookup(name string) (string, OptionValuer) {
	if v, ok := cfg.CLI.OptionValue(name); ok {
		return v, cfg.CLI
	}
	for i := len(cfg.sources) - 1; i >= 0; i-- {
		if v, ok := cfg.sources[i].OptionValue(name); ok {
			return v, cfg.sources[i]
		}
	}
	opt := cfg.FindOption(name)
	if opt == nil {
		panic(fmt.Errorf("Assertion failed: called Get on unknown option %s", name))
	}
	return opt.Default, nil
}

func (cfg *Config) Changed(name string) bool {
	_, src := cfg.lookup(name)
	return src != nil
}

func (cfg *Config) OnCLI(name string) bool {
	_, ok := cfg.CLI.OptionValues[name]
	return ok
}

func (cfg *Config) Supplier(name string) OptionValuer {
	_, src := cfg.lookup(name)
	return src
}

func (cfg *Config) GetRaw(name string) string {
	v, _ := cfg.lookup(name)
	return v
}

// Get returns an option's value, with surrounding quotes stripped.
