{"command":"cd /workspace && cat > file.go <<'EOF'
package main

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

type fileValue struct {
	value   string
	negated bool
}

type fileSection struct {
	Name   string
	Values map[string]fileValue
}

// File represents an option file.
type File struct {
	Dir                  string
	Name                 string
	IgnoreUnknownOptions bool
	sections             []*fileSection
	sectionIndex         map[string]*fileSection
	selected             []string
	contents             string
	read                 bool
	parsed               bool
	// optional restriction: for given sections, only these option names apply
	restrictSections map[string]bool
	restrictOptions  map[string]bool
	ignoredOptions   map[string]bool
}

func NewFile(paths ...string) *File {
	p := filepath.Join(paths...)
	f := &File{
		Dir:          filepath.Dir(p),
		Name:         filepath.Base(p),
		sectionIndex: make(map[string]*fileSection),
	}
	f.getOrCreateSection("")
	return f
}

func (f *File) Path() string {
	return filepath.Join(f.Dir, f.Name)
}

func (f *File) String() string {
	return f.Path()
}

func (f *File) SourceName() string {
	return f.Path()
}

func (f *File) Exists() bool {
	fi, err := os.Stat(f.Path())
	return err == nil && !fi.IsDir()
}

func (f *File) getOrCreateSection(name string) *fileSection {
	if s, ok := f.sectionIndex[name]; ok {
		return s
	}
	s := &fileSection{Name: name, Values: make(map[string]fileValue)}
	f.sections = append(f.sections, s)
	f.sectionIndex[name] = s
	return s
}

func (f *File) Read() error {
	b, err := os.ReadFile(f.Path())
	if err != nil {
		return err
	}
	f.contents = string(b)
	f.read = true
	return nil
}

func (f *File) SetContents(s string) {
	f.contents = s
	f.read = true
}

type fileParseError struct {
	msg string
}

func (e fileParseError) Error() string { return e.msg }

// Parse parses the file contents, validating against options known to cfg's
// command suite.
func (f *File) Parse(cfg *Config) error {
	if !f.read {
		if err := f.Read(); err != nil {
			return err
		}
	}
	known := cfg.CLI.Command.allSuiteOptions()
	contents := f.contents
	contents = strings.TrimPrefix(contents, "\ufeff")
	lines := strings.Split(contents, "\n")
	section := f.sectionIndex[""]
	for n, line := range lines {
		lineNum := n + 1
		line = strings.TrimSpace(line)
		if line == "" || line[0] == '#' || line[0] == ';' {
			continue
		}
		if line[0] == '[' {
			end := strings.IndexByte(line, ']')
			hash := strings.IndexByte(line, '#')
			if end < 0 || (hash >= 0 && hash < end) {
				return fileParseError{fmt.Sprintf("Parse error in %s line %d: unterminated section name", f.Path(), lineNum)}
			}
			rest := strings.TrimSpace(line[end+1:])
			if rest != "" && rest[0] != '#' {
				return fileParseError{fmt.Sprintf("Parse error in %s line %d: extra characters after section name", f.Path(), lineNum)}
			}
			section = f.getOrCreateSection(line[1:end])
			continue
		}
		// key
		keyEnd := len(line)
		hasValue := false
		for i := 0; i < len(line); i++ {
			c := line[i]
			if c == '=' {
				keyEnd = i
				hasValue = true
				break
			}
			if c == '#' {
				keyEnd = i
				break
			}
			if c == '\'' || c == '"' || c == '`' {
				return fileParseError{fmt.Sprintf("Parse error in %s line %d: Illegal character %c in option name", f.Path(), lineNum, c)}
			}
		}
		key := NormalizeOptionName(strings.TrimSpace(line[:keyEnd]))
		var value string
		if hasValue {
			var err error
			value, err = parseFileValue(line[keyEnd+1:])
			if err != nil {
				return fileParseError{fmt.Sprintf("Parse error in %s line %d: %s", f.Path(), lineNum, err)}
			}
		}
		loose := false
		if strings.HasPrefix(key, "loose-") {
			key = key[6:]
			loose = true
		}
		negated := false
		name := key
		if strings.HasPrefix(name, "skip-") {
			name = name[5:]
			negated = true
		} else if strings.HasPrefix(name, "disable-") {
			name = name[8:]
			negated = true
		} else if strings.HasPrefix(name, "enable-") {
			name = name[7:]
		}
		opt := known[name]
		if f.restrictSections != nil && f.restrictSections[section.Name] && !f.restrictOptions[name] {
			continue
		}
		if f.ignoredOptions != nil && f.ignoredOptions[name] {
			continue
		}
		if opt == nil {
			if loose || f.IgnoreUnknownOptions {
				continue
			}
			return fileParseError{fmt.Sprintf("%s line %d: Unknown option %q", f.Path(), lineNum, name)}
		}
		if opt.Type == OptionTypeBool {
			var b bool
			if hasValue {
				b = BoolValue(unquoteValue(value))
			} else {
				b = true
			}
			if negated {
				b = !b
			}
			v := ""
			if b {
				v = "1"
			}
			section.Values[name] = fileValue{value: v}
			continue
		}
		if negated {
			section.Values[name] = fileValue{value: "", negated: true}
			continue
		}
		if !hasValue && opt.RequireValue {
			return fileParseError{fmt.Sprintf("%s line %d: Missing required value for option %s", f.Path(), lineNum, name)}
		}
		section.Values[name] = fileValue{value: value}
	}
	f.parsed = true
	return nil
}

// parseFileValue strips comments and validates quoting of a raw value.
func parseFileValue(raw string) (string, error) {
	var inQuote byte
	escaped := false
	end := len(raw)
	for i := 0; i < len(raw); i++ {
		c := raw[i]
		if escaped {
			escaped = false
			continue
		}
		if c == '\\' {
			escaped = true
			continue
		}
		if inQuote != 0 {
			if c == inQuote {
				inQuote = 0
			}
			continue
		}
		if c == '\'' || c == '"' || c == '`' {
			inQuote = c
			continue
		}
		if c == '#' {
			end = i
			break
		}
	}
	if inQuote != 0 {
		return "", errors.New("Quoted value has no terminating quote")
	}
	if escaped {
		return "", errors.New("Value ends in a single backslash")
	}
	return strings.TrimSpace(raw[:end]), nil
}

// UseSection selects which sections are used, highest priority first. The
// sectionless top portion is always used as lowest priority.
func (f *File) UseSection(names ...string) {
	f.selected = names
}

func (f *File) OptionValue(name string) (string, bool) {
	for _, sname := range f.selected {
		if s, ok := f.sectionIndex[sname]; ok && sname != "" {
			if v, ok := s.Values[name]; ok {
				return v.value, true
			}
		}
	}
	if s, ok := f.sectionIndex[""]; ok {
		if v, ok := s.Values[name]; ok {
			return v.value, true
		}
	}
	return "", false
}

func (f *File) HasSection(name string) bool {
	_, ok := f.sectionIndex[name]
	return ok
}

// SectionValue returns the value of an option in a specific section only.
func (f *File) SectionValue(section, name string) (string, bool) {
	if s, ok := f.sectionIndex[section]; ok {
		if v, ok := s.Values[name]; ok {
			return v.value, true
		}
	}
	return "", false
}

func (f *File) SomeSectionHasOption(name string) bool {
	for _, s := range f.sections {
		if _, ok := s.Values[name]; ok {
			return true
		}
	}
	return false
}

func (f *File) SetOptionValue(section, name, value string) {
	s := f.getOrCreateSection(section)
	s.Values[name] = fileValue{value: value}
}

func (f *File) UnsetOptionValue(section, name string) {
	if s, ok := f.sectionIndex[section]; ok {
		delete(s.Values, name)
	}
}

// rendered returns the file contents as they would be written.
func (f *File) rendered(cfg *Config) string {
	known := map[string]*Option{}
	if cfg != nil {
		known = cfg.CLI.Command.allSuiteOptions()
	}
	var b strings.Builder
	first := true
	for _, s := range f.sections {
		if s.Name == "" && len(s.Values) == 0 {
			continue
		}
		if !first {
			b.WriteString("\n")
		}
		first = false
		if s.Name != "" {
			fmt.Fprintf(&b, "[%s]\n", s.Name)
		}
		names := make([]string, 0, len(s.Values))
		for name := range s.Values {
			names = append(names, name)
		}
		sort.Strings(names)
		for _, name := range names {
			v := s.Values[name]
			opt := known[name]
			if opt != nil && opt.Type == OptionTypeBool {
				if BoolValue(v.value) {
					fmt.Fprintf(&b, "%s\n", name)
				} else {
					fmt.Fprintf(&b, "skip-%s\n", name)
				}
				continue
			}
			if v.negated {
				fmt.Fprintf(&b, "skip-%s\n", name)
			} else if v.value == "" {
				fmt.Fprintf(&b, "%s\n", name)
			} else {
				fmt.Fprintf(&b, "%s=%s\n", name, v.value)
			}
		}
	}
	return b.String()
}

func (f *File) Write(cfg *Config, overwrite bool) error {
	flags := os.O_WRONLY | os.O_CREATE | os.O_TRUNC
	if !overwrite {
		flags |= os.O_EXCL
	}
	fh, err := os.OpenFile(f.Path(), flags, 0666)
	if err != nil {
		return err
	}
	_, err = fh.WriteString(f.rendered(cfg))
	if err2 := fh.Close(); err == nil {
		err = err2
	}
	return err
}
EOF"}

