// ParseCLI parses the command-line, returning a Config with only the CLI
// source populated.
func ParseCLI(suite *Command, args []string) (*Config, error) {
	cli := &CommandLine{
		InvokedAs:    "skeema",
		Command:      suite,
		OptionValues: make(map[string]string),
	}
	noMoreOptions := false
	for i := 0; i < len(args); i++ {
		arg := args[i]
		if noMoreOptions || len(arg) < 2 || arg[0] != '-' {
			if cli.Command.IsSuite {
				sub, ok := cli.Command.SubCommands[arg]
				if !ok {
					return nil, fmt.Errorf("Unknown command %q", arg)
				}
				cli.Command = sub
			} else {
				cli.ArgValues = append(cli.ArgValues, arg)
			}
			continue
		}
		if arg == "--" {
			noMoreOptions = true
			continue
		}
		opts := cli.Command.Options()
		if arg[1] == '-' {
			// long option
			body := arg[2:]
			name, value := body, ""
			hasValue := false
			if eq := strings.IndexByte(body, '='); eq >= 0 {
				name, value = body[:eq], body[eq+1:]
				hasValue = true
			}
			name = NormalizeOptionName(name)
			loose := false
			if strings.HasPrefix(name, "loose-") {
				name = name[6:]
				loose = true
			}
			negated := false
			if strings.HasPrefix(name, "skip-") {
				name = name[5:]
				negated = true
			} else if strings.HasPrefix(name, "disable-") {
				name = name[8:]
				negated = true
			} else if strings.HasPrefix(name, "enable-") {
				name = name[7:]
			}
			opt := opts[name]
			if opt == nil {
				if loose {
					continue
				}
				return nil, OptionNotDefinedError{name, "CLI"}
			}
			if opt.Type == OptionTypeBool {
				b := true
				if hasValue {
					b = BoolValue(value)
				}
				if negated {
					b = !b
				}
				if b {
					cli.OptionValues[name] = "1"
				} else {
					cli.OptionValues[name] = ""
				}
				continue
			}
			if negated {
				cli.OptionValues[name] = ""
				continue
			}
			if !hasValue && opt.RequireValue {
				if i+1 < len(args) && !strings.HasPrefix(args[i+1], "-") {
					value = args[i+1]
					i++
				} else {
					return nil, OptionMissingValueError{name, "CLI"}
				}
			}
			cli.OptionValues[name] = value
			continue
		}
		// short option(s)
		for j := 1; j < len(arg); j++ {
			c := arg[j]
			opt := cli.Command.OptionByShorthand(c)
			if opt == nil {
				return nil, OptionNotDefinedError{string(c), "CLI"}
			}
			if opt.Type == OptionTypeBool {
				cli.OptionValues[opt.Name] = "1"
				continue
			}
			if j+1 < len(arg) {
				cli.OptionValues[opt.Name] = arg[j+1:]
				break
			}
			if !opt.RequireValue {
				cli.OptionValues[opt.Name] = ""
				break
			}
			if i+1 < len(args) && !strings.HasPrefix(args[i+1], "-") {
				cli.OptionValues[opt.Name] = args[i+1]
				i++
				break
			}
			return nil, OptionMissingValueError{opt.Name, "CLI"}
		}
	}
	if len(cli.ArgValues) > cli.Command.MaxArgs() {
		return nil, fmt.Errorf("Extra command-line arg %q supplied; command %s takes a max of %d args", cli.ArgValues[cli.Command.MaxArgs()], cli.Command.Name, cli.Command.MaxArgs())
	}
	return NewConfig(cli), nil
}
EOF"}

