{"command":"cd /workspace && cat > help.go <<'EOF'
package main

import (
	"fmt"
	"os"
	"sort"
	"strings"
)

func (cmd *Command) usageLine() string {
	if cmd.IsSuite {
		return fmt.Sprintf("Usage:  %s [<options>] <command>", cmd.Name)
	}
	parts := []string{cmd.Root().Name, cmd.Name, "[<options>]"}
	for _, a := range cmd.args {
		if a.Required {
			parts = append(parts, "<"+a.Name+">")
		} else {
			parts = append(parts, "[<"+a.Name+">]")
		}
	}
	return "Usage:  " + strings.Join(parts, " ")
}

func titleCaseCommand(name string) string {
	parts := strings.Split(name, "-")
	for i, p := range parts {
		if p != "" {
			parts[i] = strings.ToUpper(p[:1]) + p[1:]
		}
	}
	return strings.Join(parts, "-")
}

func sortedVisible(opts []*Option) []*Option {
	result := []*Option{}
	for _, o := range opts {
		if !o.HiddenOnCLI {
			result = append(result, o)
		}
	}
	sort.Slice(result, func(i, j int) bool { return result[i].Name < result[j].Name })
	return result
}

// Usage writes help output for the command to STDOUT.
func (cmd *Command) Usage() {
	var b strings.Builder
	b.WriteString("\n")
	b.WriteString(cmd.usageLine())
	b.WriteString("\n\n")
	b.WriteString(cmd.Description)
	b.WriteString("\n\n")

	type group struct {
		title string
		opts  []*Option
	}
	var groups []group
	if cmd.IsSuite {
		// commands list handled separately
	} else {
		// command-specific options; ungrouped first then groups in definition order
		ungrouped := []*Option{}
		grouped := map[string][]*Option{}
		for _, o := range cmd.optionOrder {
			if o.Group == "" {
				ungrouped = append(ungrouped, o)
			} else {
				grouped[o.Group] = append(grouped[o.Group], o)
			}
		}
		if v := sortedVisible(ungrouped); len(v) > 0 {
			groups = append(groups, group{titleCaseCommand(cmd.Name) + " Options", v})
		}
		for _, g := range cmd.groupOrder {
			if v := sortedVisible(grouped[g]); len(v) > 0 {
				groups = append(groups, group{g + " Options", v})
			}
		}
	}
	root := cmd.Root()
	if v := sortedVisible(root.optionOrder); len(v) > 0 {
		groups = append(groups, group{"Global Options", v})
	}

	maxLen := 0
	for _, g := range groups {
		for _, o := range g.opts {
			if l := len(o.usageName()); l > maxLen {
				maxLen = l
			}
		}
	}

	if cmd.IsSuite {
		b.WriteString("Commands:\n")
		names := cmd.sortedSubCommandNames()
		nameMax := 0
		for _, n := range names {
			if len(n) > nameMax {
				nameMax = len(n)
			}
		}
		for _, n := range names {
			fmt.Fprintf(&b, "      %-*s  %s\n", nameMax, n, cmd.SubCommands[n].Summary)
		}
		b.WriteString("\n")
	}

	for _, g := range groups {
		b.WriteString(g.title + ":\n")
		for _, o := range g.opts {
			if o.Shorthand != 0 {
				fmt.Fprintf(&b, "  -%c, ", o.Shorthand)
			} else {
				b.WriteString("      ")
			}
			fmt.Fprintf(&b, "%-*s  %s\n", maxLen, o.usageName(), o.usageDescription())
		}
		b.WriteString("\n")
	}
	if cmd.IsSuite {
		b.WriteString("Complete documentation for this command suite is available online:\n")
		b.WriteString("https://www.skeema.io/docs/commands\n\n")
	} else {
		b.WriteString("Complete documentation for this command is available online:\n")
		fmt.Fprintf(&b, "https://www.skeema.io/docs/commands/%s\n\n", cmd.Name)
	}
	os.Stdout.WriteString(b.String())
}
EOF"}

