// ExitValue represents an exit code and optional message.
type ExitValue struct {
	Code    int
	Message string
}

func (ev *ExitValue) Error() string {
	return ev.Message
}

func NewExitValue(code int, format string, a ...interface{}) *ExitValue {
	msg := format
	if len(a) > 0 {
		msg = fmt.Sprintf(format, a...)
	}
	return &ExitValue{Code: code, Message: msg}
}

func logMultiline(level logLevel, msg string) {
	for _, line := range strings.Split(msg, "\n") {
		logLine(level, line)
	}
}

