package main

import (
	"fmt"
	"os"
	"runtime/debug"
	"strings"
)

var deprecatedOptions = map[string]string{
	"my-cnf":               "This option will be removed in Skeema v2, and .my.cnf will always be parsed, with additional safety logic already in place. For more information, visit https://www.skeema.io/v2-changes",
	"temp-schema-threads":  "This option will be removed in Skeema v2. Use the new temp-schema-mode enum option instead. See --help or visit https://www.skeema.io/docs/options/#temp-schema-mode",
	"concurrent-instances": "This option has been renamed to concurrent-servers. The old concurrent-instances option name remains as an alias in Skeema v1, but will be removed in Skeema v2.",
	"reuse-temp-schema":    "This option will be removed in Skeema v2.",
}

var deprecatedOrder = []string{"concurrent-instances", "my-cnf", "reuse-temp-schema", "temp-schema-threads"}

// globalFiles tracks global option files that were added as sources.
var globalFiles []*File

type panicError struct {
	location string
	msg      string
}

func emitPanic(location, msg string) {
	logErrorf("Uncaught panic in %s: %s", location, msg)
	logError("This situation indicates a bug in Skeema. Use --debug to view full stack trace.")
	logError("Please file an issue report at https://github.com/skeema/skeema/issues with any available background information.")
	if currentLogLevel >= levelDebug {
		logDebug(string(debug.Stack()))
	}
	logDebugf("Exit code %d", CodeFatalError)
	os.Exit(CodeFatalError)
}

func panicHandler() {
	if r := recover(); r != nil {
		if pe, ok := r.(panicError); ok {
			emitPanic(pe.location, pe.msg)
		}
		emitPanic("main", fmt.Sprint(r))
	}
}

func environmentFor(cfg *Config) (string, bool) {
	cmd := cfg.CLI.Command
	for i, a := range cmd.args {
		if a.Name == "environment" {
			if i < len(cfg.CLI.ArgValues) {
				return cfg.CLI.ArgValues[i], true
			}
			return a.Default, true
		}
	}
	return "", false
}

var myCnfWhitelist = map[string]bool{"user": true, "password": true, "port": true, "socket": true, "ssl-mode": true}

func addGlobalConfigFiles(cfg *Config) error {
	env, hasEnv := environmentFor(cfg)
	sections := []string{}
	if hasEnv && env != "" {
		sections = append(sections, env)
	}
	paths := []string{"/etc/skeema", "/usr/local/etc/skeema"}
	home := homeDir()
	for _, p := range paths {
		f := NewFile(p)
		addGlobalFile(cfg, f, sections)
	}
	if home != "" {
		if cfg.GetBool("my-cnf") {
			f := NewFile(home, ".my.cnf")
			if f.Exists() {
				if err := parseMyCnf(cfg, f); err != nil {
					logWarnf("Ignoring global option file %s due to parse error: %s", f.Path(), err)
				} else {
					f.UseSection("skeema", "client", "mysql")
					cfg.AddSource(f)
					globalFiles = append(globalFiles, f)
				}
			}
		}
		f := NewFile(home, ".skeema")
		addGlobalFile(cfg, f, sections)
	}

	// deprecation warnings
	for _, name := range deprecatedOrder {
		if cfg.OnCLI(name) {
			logWarnf("Option --%s is deprecated. %s", name, deprecatedOptions[name])
		}
	}
	for _, f := range globalFiles {
		if !f.parsed {
			panic(panicError{"github.com/skeema/mybase.(*File).DeprecationWarnings at github.com/skeema/mybase@v1.2.0/file.go:420", "Call to DeprecationWarnings() on unparsed file " + f.Path()})
		}
		emitFileDeprecations(f)
	}
	return nil
}

func emitFileDeprecations(f *File) {
	for _, name := range deprecatedOrder {
		if f.SomeSectionHasOption(name) {
			logWarnf("%s: Option %s is deprecated. %s", f.Path(), name, deprecatedOptions[name])
		}
	}
}

func addGlobalFile(cfg *Config, f *File, sections []string) {
	if !f.Exists() {
		return
	}
	if err := f.Read(); err != nil {
		logWarnf("Ignoring global option file %s due to read error: %s", f.Path(), err)
		return
	}
	if err := f.Parse(cfg); err != nil {
		logWarnf("Ignoring global option file %s due to parse error: %s", f.Path(), err)
		return
	}
	f.UseSection(sections...)
	cfg.AddSource(f)
	globalFiles = append(globalFiles, f)
}

// parseMyCnf parses ~/.my.cnf with special restrictions.
func parseMyCnf(cfg *Config, f *File) error {
	if err := f.Read(); err != nil {
		return err
	}
	known := cfg.CLI.Command.allSuiteOptions()
	// First pass: syntax and value validation of relevant lines
	lines := strings.Split(strings.TrimPrefix(f.contents, "\ufeff"), "\n")
	var b strings.Builder
	section := ""
	unparsed := false
	for n, line := range lines {
		lineNum := n + 1
		_ = lineNum
		t := strings.TrimSpace(line)
		if t == "" || t[0] == '#' || t[0] == ';' {
			b.WriteString("\n")
			continue
		}
		if t[0] == '[' {
			end := strings.IndexByte(t, ']')
			if end > 0 {
				section = t[1:end]
			}
			b.WriteString(line + "\n")
			continue
		}
		keyEnd := len(t)
		hasValue := false
		for i := 0; i < len(t); i++ {
			if t[i] == '=' {
				keyEnd = i
				hasValue = true
				break
			}
			if t[i] == '#' {
				keyEnd = i
				break
			}
		}
		key := NormalizeOptionName(strings.TrimSpace(t[:keyEnd]))
		name := strings.TrimPrefix(key, "loose-")
		for _, p := range []string{"skip-", "disable-", "enable-"} {
			if strings.HasPrefix(name, p) {
				name = name[len(p):]
				break
			}
		}
		switch section {
		case "client", "mysql":
			if strings.ContainsAny(t[:keyEnd], "'\"`") {
				b.WriteString(line + "\n")
				continue
			}
			if !myCnfWhitelist[name] {
				b.WriteString("\n")
				continue
			}
		case "skeema":
			opt := known[name]
			if opt != nil && opt.Type == OptionTypeString && opt.RequireValue && !hasValue && !myCnfWhitelist[name] && !strings.HasPrefix(key, "skip-") && !strings.HasPrefix(key, "disable-") && !unparsed {
				unparsed = true
			}
		default:
			if strings.ContainsAny(t[:keyEnd], "'\"`") {
				b.WriteString(line + "\n")
				continue
			}
			b.WriteString("\n")
			continue
		}
		b.WriteString(line + "\n")
	}
	orig := f.contents
	f.contents = b.String()
	f.IgnoreUnknownOptions = true
	f.ignoredOptions = map[string]bool{}
	err := f.Parse(cfg)
	f.contents = orig
	if err != nil {
		if unparsed {
			if strings.Contains(err.Error(), "Missing required value") {
				// determine which error comes first
				fe := err.Error()
				if !errBeforeUnparsed(fe, f, known) {
					f.parsed = false
					return nil
				}
			}
		}
		return err
	}
	if unparsed {
		f.parsed = false
	}
	return nil
}

// errBeforeUnparsed reports whether the given parse error refers to a line
// earlier than the first line triggering the unparsed-file condition.
func errBeforeUnparsed(errMsg string, f *File, known map[string]*Option) bool {
	lines := strings.Split(f.contents, "\n")
	section := ""
	for n, line := range lines {
		t := strings.TrimSpace(line)
		if t == "" || t[0] == '#' || t[0] == ';' {
			continue
		}
		if t[0] == '[' {
			if end := strings.IndexByte(t, ']'); end > 0 {
				section = t[1:end]
			}
			continue
		}
		if strings.Contains(errMsg, fmt.Sprintf(" line %d:", n+1)) {
			return true
		}
		if section == "skeema" {
			key := NormalizeOptionName(strings.TrimSpace(strings.SplitN(strings.SplitN(t, "#", 2)[0], "=", 2)[0]))
			name := strings.TrimPrefix(key, "loose-")
			opt := known[name]
			if opt != nil && opt.Type == OptionTypeString && opt.RequireValue && !strings.Contains(t, "=") && !myCnfWhitelist[name] {
				return false
			}
		}
	}
	return true
}

func checkHostSchemaLimitations(cfg *Config) error {
	cmdName := cfg.CLI.Command.Name
	for _, name := range []string{"host", "schema"} {
		if cfg.Get(name) == "" {
			continue
		}
		if name == "host" && (cmdName == "init" || cmdName == "add-environment") {
			continue
		}
		if name == "schema" && cmdName == "init" {
			continue
		}
		src := cfg.Supplier(name)
		return NewExitValue(CodeBadConfig, "The %s option cannot be set via %s for this command. For more information, visit https://www.skeema.io/docs/config/#limitations-on-host-and-schema-options", name, src.SourceName())
	}
	return nil
}

func processSpecialGlobalOptions(cfg *Config) error {
	if cfg.CLI.noValue["password"] {
		os.Stderr.WriteString("Enter password: ")
		pw, err := readPasswordFromTerminal()
		os.Stderr.WriteString("\n")
		if err != nil {
			logError(err.Error())
			return NewExitValue(CodeBadConfig, "Interactive password prompting requires an input terminal. To supply a password non-interactively, configure the password value in a global option file, or supply it directly on the command-line, or set the $MYSQL_PWD environment variable. For more information, see https://www.skeema.io/docs/options/#password")
		}
		cfg.CLI.OptionValues["password"] = pw
		delete(cfg.CLI.noValue, "password")
	}
	if cfg.GetBool("debug") {
		currentLogLevel = levelDebug
	}
	return nil
}
EOF"}

