		_ = lineNum
		t := strings.TrimSpace(line)
		if t == "" || t[0] == '#' || t[0] == ';' {
			b.WriteString("\n")
			continue
		}
		if t[0] == '[' {
			end := strings.IndexByte(t, ']')
			if end > 0 {
				section = t[1:end]
			}
			b.WriteString(line + "\n")
			continue
		}
		keyEnd := len(t)
		hasValue := false
		for i := 0; i < len(t); i++ {
			if t[i] == '=' {
				keyEnd = i
				hasValue = true
				break
			}
			if t[i] == '#' {
				keyEnd = i
				break
			}
		}
		key := NormalizeOptionName(strings.TrimSpace(t[:keyEnd]))
		name := strings.TrimPrefix(key, "loose-")
		for _, p := range []string{"skip-", "disable-", "enable-"} {
			if strings.HasPrefix(name, p) {
				name = name[len(p):]
				break
			}
		}
		switch section {
		case "client", "mysql":
			if strings.ContainsAny(t[:keyEnd], "'\"`") {
				b.WriteString(line + "\n")
				continue
			}
			if !myCnfWhitelist[name] {
				b.WriteString("\n")
				continue
			}
		case "skeema":
			opt := known[name]
			if opt != nil && opt.Type == OptionTypeString && opt.RequireValue && !hasValue && !myCnfWhitelist[name] && !strings.HasPrefix(key, "skip-") && !strings.HasPrefix(key, "disable-") && !unparsed {
				unparsed = true
			}
		default:
			if strings.ContainsAny(t[:keyEnd], "'\"`") {
				b.WriteString(line + "\n")
				continue
			}
			b.WriteString("\n")
			continue
		}
		b.WriteString(line + "\n")
	}
	orig := f.contents
	f.contents = b.String()
	f.IgnoreUnknownOptions = true
	f.ignoredOptions = map[string]bool{}
	err := f.Parse(cfg)
	f.contents = orig
	if err != nil {
		if unparsed {
			if strings.Contains(err.Error(), "Missing required value") {
				// determine which error comes first
				fe := err.Error()
				if !errBeforeUnparsed(fe, f, known) {
					f.parsed = false
					return nil
				}
			}
		}
		return err
	}
	if unparsed {
		f.parsed = false
	}
	return nil
}

// errBeforeUnparsed reports whether the given parse error refers to a line
// earlier than the first line triggering the unparsed-file condition.
func errBeforeUnparsed(errMsg string, f *File, known map[string]*Option) bool {
	lines := strings.Split(f.contents, "\n")
	section := ""
	for n, line := range lines {
		t := strings.TrimSpace(line)
		if t == "" || t[0] == '#' || t[0] == ';' {
			continue
		}
		if t[0] == '[' {
			if end := strings.IndexByte(t, ']'); end > 0 {
				section = t[1:end]
			}
			continue
		}
		if strings.Contains(errMsg, fmt.Sprintf(" line %d:", n+1)) {
			return true
		}
		if section == "skeema" {
			key := NormalizeOptionName(strings.TrimSpace(strings.SplitN(strings.SplitN(t, "#", 2)[0], "=", 2)[0]))
			name := strings.TrimPrefix(key, "loose-")
			opt := known[name]
			if opt != nil && opt.Type == OptionTypeString && opt.RequireValue && !strings.Contains(t, "=") && !myCnfWhitelist[name] {
				return false
			}
		}
	}
	return true
}

func checkHostSchemaLimitations(cfg *Config) error {
	cmdName := cfg.CLI.Command.Name
	for _, name := range []string{"host", "schema"} {
		if cfg.Get(name) == "" {
			continue
		}
		if name == "host" && (cmdName == "init" || cmdName == "add-environment") {
			continue
		}
		if name == "schema" && cmdName == "init" {
			continue
		}
		src := cfg.Supplier(name)
		return NewExitValue(CodeBadConfig, "The %s option cannot be set via %s for this command. For more information, visit https://www.skeema.io/docs/config/#limitations-on-host-and-schema-options", name, src.SourceName())
	}
	return nil
}

func processSpecialGlobalOptions(cfg *Config) error {
	if cfg.CLI.noValue["password"] {
		os.Stderr.WriteString("Enter password: ")
		pw, err := readPasswordFromTerminal()
		os.Stderr.WriteString("\n")
		if err != nil {
			logError(err.Error())
			return NewExitValue(CodeBadConfig, "Interactive password prompting requires an input terminal. To supply a password non-interactively, configure the password value in a global option file, or supply it directly on the command-line, or set the $MYSQL_PWD environment variable. For more information, see https://www.skeema.io/docs/options/#password")
		}
		cfg.CLI.OptionValues["password"] = pw
		delete(cfg.CLI.noValue, "password")
	}
	if cfg.GetBool("debug") {
		currentLogLevel = levelDebug
	}
	return nil
}
