package main

import (
	"fmt"
	"os"
	"strings"
	"unicode"
)

type StatementType int

const (
	StatementTypeUnknown StatementType = iota
	StatementTypeCreate
	StatementTypeUse
	StatementTypeDelimiter
)

type ObjectType string

const (
	ObjectTypeTable ObjectType = "table"
	ObjectTypeProc  ObjectType = "procedure"
	ObjectTypeFunc  ObjectType = "function"
)

type Statement struct {
	File            string
	LineNo          int
	CharNo          int
	Text            string
	Type            StatementType
	ObjectType      ObjectType
	ObjectName      string
	ObjectQualifier string
	Delimiter       string
}

func (s *Statement) Location() string {
	return fmt.Sprintf("%s:%d:%d", s.File, s.LineNo, s.CharNo)
}

type tokenType int

const (
	tokWord tokenType = iota
	tokString
	tokDQString
	tokBacktick
	tokSymbol
	tokNumber
)

type token struct {
	typ tokenType
	val string // for quoted: unescaped contents
	raw string
}

type sqlParseError struct {
	file string
	msg  string
}

func (e *sqlParseError) Error() string {
	return fmt.Sprintf("File %s: %s", e.file, e.msg)
}

type sqlPanic struct {
	msg string
}

// sqlScanner scans a file's contents into statements.
type sqlScanner struct {
	file  string
	runes []rune
	pos   int
	line  int
	col   int
}

func (s *sqlScanner) peek(off int) rune {
	if s.pos+off < len(s.runes) {
		return s.runes[s.pos+off]
	}
	return 0
}

func (s *sqlScanner) eof() bool { return s.pos >= len(s.runes) }

func (s *sqlScanner) advance() rune {
	c := s.runes[s.pos]
	s.pos++
	if c == '\n' {
		s.line++
		s.col = 1
	} else {
		s.col++
	}
	return c
}

func (s *sqlScanner) hasPrefix(p string) bool {
	pr := []rune(p)
	if s.pos+len(pr) > len(s.runes) {
		return false
	}
	for i, c := range pr {
		if s.runes[s.pos+i] != c {
			return false
		}
	}
	return true
}

func isSpaceRune(c rune) bool {
	return c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f' || c == '\v'
}

func isWordRune(c rune) bool {
	return c == '_' || c == '$' || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c > 127 && (unicode.IsLetter(c) || unicode.IsDigit(c) || unicode.IsMark(c) || c >= 0x80)
}

// skipComment attempts to skip a comment at the current position; returns
// true if one was skipped.
func (s *sqlScanner) skipComment() (bool, error) {
	c := s.peek(0)
	if c == '#' {
		for !s.eof() && s.peek(0) != '\n' {
			s.advance()
		}
		return true, nil
	}
	if c == '-' && s.peek(1) == '-' && (s.pos+2 >= len(s.runes) || isSpaceRune(s.peek(2))) {
		for !s.eof() && s.peek(0) != '\n' {
			s.advance()
		}
		return true, nil
	}
	if c == '/' && s.peek(1) == '*' {
		line, col := s.line, s.col
		s.advance()
		s.advance()
		for {
			if s.eof() {
				return false, &sqlParseError{s.file, fmt.Sprintf("Comment starting with /* is never closed at line %d, column %d", line, col)}
			}
			if s.peek(0) == '*' && s.peek(1) == '/' {
				s.advance()
				s.advance()
				return true, nil
			}
			s.advance()
		}
	}
	return false, nil
}

// scanQuoted scans a quoted string/identifier at the current position.
func (s *sqlScanner) scanQuoted() (string, error) {
	q := s.peek(0)
	line, col := s.line, s.col
	s.advance()
	var b strings.Builder
	for {
		if s.eof() {
			what := "String"
			if q == '`' {
				what = "Identifier"
			}
			return "", &sqlParseError{s.file, fmt.Sprintf("%s is missing closing quote at line %d, column %d", what, line, col)}
		}
		c := s.advance()
		if c == '\\' && q != '`' {
			if !s.eof() {
				n := s.advance()
				b.WriteRune('\\')
				b.WriteRune(n)
			}
			continue
		}
		if c == q {
			if s.peek(0) == q {
				s.advance()
				b.WriteRune(q)
				continue
			}
			return b.String(), nil
		}
		b.WriteRune(c)
	}
}

// ParseStatementsInFile reads and splits a file into statements.
func ParseStatementsInFile(path string) ([]*Statement, error) {
	b, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	return ParseStatementsInString(path, string(b))
}

func ParseStatementsInString(path, contents string) ([]*Statement, error) {
	s := &sqlScanner{file: path, runes: []rune(contents), line: 1, col: 1}
	delim := ";"
	var stmts []*Statement
	for {
		// skip whitespace and comments between statements
		for !s.eof() {
			c := s.peek(0)
			if isSpaceRune(c) {
				s.advance()
				continue
			}
