// ParseDir parses the base directory, including ancestor option files.
func ParseDir(dirPath string, cfg *Config) (*Dir, error) {
	abs, err := filepath.Abs(dirPath)
	if err != nil {
		return nil, err
	}
	abs = filepath.Clean(abs)
	fi, err := os.Stat(abs)
	if err != nil {
		return nil, err
	}
	if !fi.IsDir() {
		return nil, fmt.Errorf("Path %s is not a directory", abs)
	}
	env := dirEnvironment(cfg)
	dirCfg := cfg.Clone()
	// ancestor option files
	home := filepath.Clean(homeDir())
	var ancestors []*File
	cur := abs
	for {
		if cur == home {
			break
		}
		parent := filepath.Dir(cur)
		if parent == cur {
			break
		}
		// check .git in cur (stop after processing cur's parent? no: stop at repo root)
		if hasGit(cur) {
			break
		}
		cur = parent
		if cur == home {
			break
		}
		f := NewFile(cur, ".skeema")
		if f.Exists() {
			if err := f.Read(); err != nil {
				return nil, err
			}
			if err := f.Parse(cfg); err != nil {
				return nil, &configError{err.Error()}
			}
			f.UseSection(env)
			ancestors = append(ancestors, f)
		}
		if hasGit(cur) {
			break
		}
	}
	for i := len(ancestors) - 1; i >= 0; i-- {
		dirCfg.AddSource(ancestors[i])
		emitFileDeprecations(ancestors[i])
	}
	dir := &Dir{Path: abs, Config: dirCfg, baseParent: filepath.Dir(abs), env: env}
	dir.parseContents()
	if dir.ParseError != nil {
		return nil, dir.ParseError
	}
	return dir, nil
}

func hasGit(path string) bool {
	_, err := os.Lstat(filepath.Join(path, ".git"))
	return err == nil
}

func (dir *Dir) parseContents() {
	f := NewFile(dir.Path, ".skeema")
	if f.Exists() {
		if err := f.Read(); err != nil {
			dir.ParseError = err
			return
		}
