		stmts, err := ParseStatementsInFile(filepath.Join(dir.Path, name))
		if err != nil {
			dir.ParseError = err
			return
		}
		current := ""
		for _, stmt := range stmts {
			switch stmt.Type {
			case StatementTypeUse:
				current = stmt.ObjectName
			case StatementTypeCreate:
				schemaName := current
				if stmt.ObjectQualifier != "" {
					schemaName = stmt.ObjectQualifier
				}
