					return
				}
				ls.Creates[key] = stmt
				ls.Order = append(ls.Order, stmt)
			case StatementTypeUnknown:
				dir.IgnoredStatements = append(dir.IgnoredStatements, stmt)
			}
		}
	}
	if dir.OptionFile != nil && dir.OptionFile.SomeSectionHasOption("schema") && dir.Config.Changed("schema") {
		if _, ok := schemaIndex[""]; !ok {
			ls := &LogicalSchema{Name: "", Creates: make(map[objectKey]*Statement)}
			schemaIndex[""] = ls
			dir.LogicalSchemas = append([]*LogicalSchema{ls}, dir.LogicalSchemas...)
		}
	}
