func EscapeIdentifier(name string) string {
	return "`" + strings.Replace(name, "`", "``", -1) + "`"
}

// Subdirs returns parsed subdirectories (not hidden, not symlinks), sorted.
func (dir *Dir) Subdirs() ([]*Dir, error) {
	entries, err := os.ReadDir(dir.Path)
	if err != nil {
		return nil, err
	}
	var result []*Dir
	for _, e := range entries {
		name := e.Name()
		if strings.HasPrefix(name, ".") {
			continue
		}
		if !e.IsDir() {
			continue
		}
		sub := &Dir{
			Path:       filepath.Join(dir.Path, name),
			Config:     dir.Config.Clone(),
			baseParent: dir.baseParent,
			env:        dir.env,
		}
		sub.parseContents()
		result = append(result, sub)
	}
	return result, nil
}

// HasSchema returns true if this dir's own option file defines a schema in
// any section, or if *.sql files reference named schemas.
func (dir *Dir) HasSchema() bool {
	if dir.OptionFile != nil && dir.OptionFile.SomeSectionHasOption("schema") {
		return true
	}
	for _, ls := range dir.LogicalSchemas {
		if ls.Name != "" {
			return true
		}
	}
	return false
}

func (dir *Dir) hasNamedSchemas() bool {
	for _, ls := range dir.LogicalSchemas {
		if ls.Name != "" {
			return true
		}
	}
	return false
}
