{"command":"cd /workspace && cat > instances.go <<'EOF'
package main

import (
	"bytes"
	"errors"
	"fmt"
	"net"
	"os"
	"os/exec"
	"regexp"
	"strconv"
	"strings"
	"time"
)

type Instance struct {
	Host       string
	Port       int
	SocketPath string
	User       string
	Password   string
	promptPass bool
}

func (inst *Instance) String() string {
	if inst.SocketPath != "" {
		return inst.Host + ":" + inst.SocketPath
	}
	return fmt.Sprintf("%s:%d", inst.Host, inst.Port)
}

// Connect attempts to establish a connection, returning an error on failure.
func (inst *Instance) Connect() error {
	var network, addr string
	if inst.SocketPath != "" {
		network, addr = "unix", inst.SocketPath
	} else {
		network = "tcp"
		h := inst.Host
		if strings.HasPrefix(h, "[") && strings.HasSuffix(h, "]") {
			h = h[1 : len(h)-1]
		}
		addr = net.JoinHostPort(h, strconv.Itoa(inst.Port))
	}
	d := net.Dialer{Timeout: 5 * time.Second}
	conn, err := d.Dial(network, addr)
	if err != nil {
		return err
	}
	defer conn.Close()
	return mysqlHandshake(conn, inst)
}

// SplitHostOptionalPort splits a host string with an optional port.
func SplitHostOptionalPort(hostaddr string) (string, int, error) {
	if len(hostaddr) == 0 {
		return "", 0, errors.New("Cannot parse blank host address")
	}
	if (hostaddr[0] == '[' && hostaddr[len(hostaddr)-1] == ']') || !strings.Contains(hostaddr, ":") {
		return hostaddr, 0, nil
	}
	host, portString, err := net.SplitHostPort(hostaddr)
	if err != nil {
		return "", 0, err
	}
	port, err := strconv.Atoi(portString)
	if err != nil {
		return "", 0, err
	}
	if port < 1 {
		return "", 0, fmt.Errorf("invalid port %d supplied", port)
	}
	if strings.Contains(host, ":") {
		host = "[" + host + "]"
	}
	return host, port, nil
}

var hostWrapperVarRe = regexp.MustCompile(`\{([^{}]*)\}`)

// interpolateCommand replaces {VARS} in a command string.
func interpolateCommand(command string, vars map[string]string) (string, error) {
	var outErr error
	result := hostWrapperVarRe.ReplaceAllStringFunc(command, func(m string) string {
		name := strings.ToUpper(m[1 : len(m)-1])
		v, ok := vars[name]
		if !ok {
			if outErr == nil {
				outErr = fmt.Errorf("Unknown variable %s", name)
			}
			return m
		}
		return shellEscape(v)
	})
	return result, outErr
}

func shellEscape(s string) string {
	if s == "" {
		return "''"
	}
	safe := true
	for _, c := range s {
		if !(c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' || c >= '0' && c <= '9' || strings.ContainsRune("-_./:@%+=,", c)) {
			safe = false
			break
		}
	}
	if safe {
		return s
	}
	return "'" + strings.Replace(s, "'", `'"'"'`, -1) + "'"
}

func runShellCommand(command string) (string, error) {
	cmd := exec.Command("/bin/sh", "-c", command)
	var out bytes.Buffer
	cmd.Stdout = &out
	cmd.Stderr = os.Stderr
	cmd.Stdin = os.Stdin
	err := cmd.Run()
	return out.String(), err
}

// HostList returns the list of host strings for a dir, possibly by shelling
// out to the host-wrapper.
func (dir *Dir) HostList() ([]string, error) {
	cfg := dir.Config
	if hw := cfg.Get("host-wrapper"); hw != "" {
		vars := map[string]string{
			"HOST":        cfg.Get("host"),
			"ENVIRONMENT": dir.env,
			"DIRNAME":     dir.BaseName(),
			"DIRPATH":     dir.Path,
			"SCHEMA":      cfg.Get("schema"),
		}
		command, err := interpolateCommand(hw, vars)
		if err != nil {
			return nil, err
		}
		out, err := runShellCommand(command)
		if err != nil {
			return nil, err
		}
		return strings.Fields(strings.Replace(out, ",", " ", -1)), nil
	}
	return cfg.GetSlice("host", ',', true), nil
}

// Instances returns the instances for this dir.
func (dir *Dir) Instances() ([]*Instance, error) {
	hosts, err := dir.HostList()
	if err != nil {
		return nil, err
	}
	cfg := dir.Config
	var result []*Instance
	for _, h := range hosts {
		host, port, err := SplitHostOptionalPort(h)
		if err != nil {
			return nil, err
		}
		inst := &Instance{Host: host, User: cfg.Get("user"), Password: cfg.Get("password"), promptPass: cfg.IsValueless("password")}
		portSupplied := port > 0
		if port == 0 {
			port = cfg.GetIntOrDefault("port")
			if port <= 0 {
				port = 3306
			}
			portSupplied = cfg.Changed("port")
		}
		inst.Port = port
		if host == "localhost" && !(port > 0 && strings.Contains(h, ":")) && (cfg.Changed("socket") || !portSupplied) {
			inst.SocketPath = cfg.Get("socket")
		}
		result = append(result, inst)
	}
	return result, nil
}

// FirstInstance returns the first reachable instance for the dir.
func (dir *Dir) FirstInstance() (*Instance, error) {
	insts, err := dir.Instances()
	if err != nil {
		return nil, err
	}
