	if len(parts) >= 1 {
		f.Major, _ = strconv.Atoi(parts[0])
	}
	if len(parts) >= 2 {
		f.Minor, _ = strconv.Atoi(parts[1])
	}
	if len(parts) >= 3 {
		p := parts[2]
		for i, c := range p {
			if c < '0' || c > '9' {
				p = p[:i]
				break
			}
		}
		f.Patch, _ = strconv.Atoi(p)
	}
	if f.Vendor == "unknown" && !strings.Contains(s, ":") {
		f.Major, f.Minor, f.Patch = 0, 0, 0
	}
	return f
}

func (f Flavor) String() string {
	return fmt.Sprintf("%s:%d.%d", f.Vendor, f.Major, f.Minor)
}

func (f Flavor) IsUnknown() bool {
	return f.Vendor == "unknown" && f.Major == 0 && f.Minor == 0
}

func (f Flavor) Known() bool {
	return f.Vendor != "unknown" && (f.Major != 0 || f.Minor != 0)
}

func (f Flavor) familyName() string {
	if f.Vendor == "mariadb" {
		return "MariaDB"
	}
	return "MySQL"
}

func (f Flavor) atLeast(major, minor int) bool {
	return f.Major > major || (f.Major == major && f.Minor >= minor)
}

func (f Flavor) Supported() bool {
	if f.Vendor == "mariadb" {
		return f.atLeast(10, 1)
	}
	return f.atLeast(5, 5)
}

func (f Flavor) Deprecated() bool {
	if f.Vendor == "mariadb" {
		return f.Major == 10 && f.Minor == 1
	}
	return f.Major == 5 && f.Minor == 5
}

func (f Flavor) TooNew() bool {
	if f.Vendor == "mariadb" {
		return f.atLeast(12, 3)
	}
	return f.atLeast(9, 7)
}

