			return &workspaceError{CodeFatalError, errDockerNotFound}
		}
		return &workspaceError{CodeFatalError, errors.New("workspace=docker is not available in this environment")}
	}
	if cfg.Get("host") == "" && cfg.Get("host-wrapper") == "" {
		return &workspaceError{CodeBadConfig, fmt.Errorf("This command needs either a host (with workspace=temp-schema) or flavor (with workspace=docker), but one is not configured for environment %q", dir.env)}
