package main

import (
	"errors"
	"fmt"
	"sort"
)

func plural(n int, singular, pluralForm string) string {
	if n == 1 {
		return fmt.Sprintf("%d %s", n, singular)
	}
	return fmt.Sprintf("%d %s", n, pluralForm)
}

func parseBaseDir(cfg *Config) (*Dir, error) {
	dir, err := ParseDir(".", cfg)
	if err != nil {
		var ce *configError
		if errors.As(err, &ce) {
			return nil, NewExitValue(CodeBadConfig, err.Error())
		}
		return nil, err
	}
	return dir, nil
}

func upgradeNoticeFormat(cfg *Config) {
	if !cfg.Changed("format") {
		logDebug("Upgrade notice: the --format option, which currently defaults to true in Skeema v1, will change to default to false in Skeema v2. For more information, visit https://www.skeema.io/v2-changes")
	}
}

type lintTotals struct {
	warnings  int
	errors    int
	skipped   int
	skipCode  int
}

func LintHandler(cfg *Config) error {
	upgradeNoticeFormat(cfg)
	dir, err := parseBaseDir(cfg)
	if err != nil {
		return err
	}
	totals := &lintTotals{}
	lintWalker(dir, totals, 5)
	if totals.skipped > 0 {
		return NewExitValue(totals.skipCode, "Skipped %s due to fatal errors", plural(totals.skipped, "operation", "operations"))
	}
	if totals.errors > 0 {
		msg := fmt.Sprintf("Found %s", plural(totals.errors, "error", "errors"))
		if totals.warnings > 0 {
			msg += fmt.Sprintf(" and %s", plural(totals.warnings, "warning", "warnings"))
		}
		return NewExitValue(CodeFatalError, msg)
	}
	if totals.warnings > 0 {
		return NewExitValue(CodeDifferencesFound, "Found %s", plural(totals.warnings, "warning", "warnings"))
	}
	return nil
}

func (t *lintTotals) skip(code int) {
