package main

import (
	"fmt"
)

type target struct {
	dir  *Dir
	inst *Instance
}

func DiffHandler(cfg *Config) error {
	return diffPush(cfg, true)
}

func PushHandler(cfg *Config) error {
	return diffPush(cfg, cfg.GetBool("dry-run"))
}

func concurrencyCheck(cfg *Config) error {
	name := "concurrent-servers"
	if cfg.Changed("concurrent-instances") {
		name = "concurrent-instances"
	}
	n, err := cfg.GetInt(name)
	if err != nil {
		return NewExitValue(CodeBadConfig, err.Error())
	}
	if n < 1 {
		return NewExitValue(CodeBadConfig, "concurrent-instances cannot be less than 1")
	}
	return nil
}

func diffPush(cfg *Config, dryRun bool) error {
	dir, err := parseBaseDir(cfg)
	if err != nil {
		return err
	}
	if err := concurrencyCheck(dir.Config); err != nil {
		return err
	}
	targets, skipCount := targetsForDir(dir, 5, true)
	for _, t := range targets {
		if err := t.inst.Connect(); err != nil {
			logErrorf("Skipping %s for %s: %s", t.inst, t.dir, err)
			skipCount++
			continue
		}
		logErrorf("Skipping %s for %s: %s", t.inst, t.dir, "unable to process")
		skipCount++
	}
	if skipCount > 0 {
		noun := "problem"
		if skipCount > 1 {
			noun = "problems"
		}
		return NewExitValue(CodeFatalError, "Skipped %s due to %s", plural(skipCount, "operation", "operations"), noun)
	}
	return nil
}

func targetsForDir(dir *Dir, maxDepth int, isRoot bool) (targets []*target, skipCount int) {
	if dir.ParseError != nil {
		logErrorf("Skipping %s: %s", dir, dir.ParseError)
		return nil, 1
	}
	if dir.HasSchema() {
		ts, skipped := targetsForLeafDir(dir)
		targets = append(targets, ts...)
		skipCount += skipped
	}
	if maxDepth <= 0 {
		return
	}
	subdirs, err := dir.Subdirs()
	if err != nil {
		logErrorf("Unable to list subdirs of %s: %s", dir, err)
		return targets, skipCount + 1
	}
	for _, sub := range subdirs {
		ts, skipped := targetsForDir(sub, maxDepth-1, false)
		targets = append(targets, ts...)
		skipCount += skipped
	}
	return
}

func targetsForLeafDir(dir *Dir) ([]*target, int) {
	_, schemaDefined := dir.Config.lookupDefined("schema")
	if !schemaDefined && !dir.hasNamedSchemas() {
		logWarnf("Skipping %s: no schema defined for environment %q", dir, dir.env)
		logWarn("Other environments do define a schema name. Refer to the .skeema file in this directory for details.")
		return nil, 0
	}
	if dir.Config.Get("host") == "" {
		logWarnf("Skipping %s: no host defined for environment %q", dir, dir.env)
		if dir.Config.Get("host-wrapper") != "" {
			logWarn("The host-wrapper option controls which hosts this directory maps to, but a .skeema file also needs to set the host option to some value (even just a placeholder value) for this command to properly map directories to hosts and schemas.")
		} else {
			logWarnf("This command requires a hostname, which can be specified using the host option in a [%s] section of the .skeema file in this directory, or in a parent directory.", dir.env)
		}
		return nil, 0
	}
	if dir.Config.GetBool("first-only") {
		inst, err := dir.FirstInstance()
		if err != nil {
			logErrorf("Skipping %s: %s", dir, err)
			return nil, 1
		}
		if inst == nil {
			warnEmptyInstances(dir)
			return nil, 0
		}
		return []*target{{dir: dir, inst: inst}}, 0
	}
	insts, err := dir.Instances()
	if err != nil {
		logErrorf("Skipping %s: %s", dir, err)
		return nil, 1
	}
	if len(insts) == 0 {
		warnEmptyInstances(dir)
		return nil, 0
	}
	var result []*target
	for _, inst := range insts {
		result = append(result, &target{dir: dir, inst: inst})
	}
	return result, 0
}

func warnEmptyInstances(dir *Dir) {
	logWarnf("Skipping %s: directory maps to an empty list of database servers", dir)
	if dir.Config.Get("host-wrapper") != "" {
		logWarn("The host-wrapper option controls which hosts this directory maps to, but the executed script returned no hostnames.")
	}
}

