// ParseConnectOptions parses a connect-options string.
func ParseConnectOptions(input string) ([]connectOption, error) {
	var result []connectOption
	seen := map[string]bool{}
	var isQuote, isEscaped bool
	startToken := 0
	name := ""
	for n, c := range input {
		if isEscaped {
			isEscaped = false
			continue
		}
		if isQuote {
			if c == '\\' {
				isEscaped = true
			} else if c == '\'' {
				isQuote = false
			}
			continue
