	if err == nil && fi.IsDir() {
		abs, _ := filepath.Abs(dirName)
		if _, err := os.Stat(filepath.Join(abs, ".skeema")); err == nil {
			return NewExitValue(CodeBadConfig, "Cannot use dir %s: already has .skeema file", abs)
		}
		matches, _ := filepath.Glob(filepath.Join(abs, "*.sql"))
		for _, m := range matches {
			if mfi, err := os.Stat(m); err == nil && mfi.Mode().IsRegular() {
				return NewExitValue(CodeBadConfig, "Cannot use dir %s: already contains *.sql files", abs)
			}
		}
	} else {
		if err := os.MkdirAll(dirName, 0777); err != nil {
			return NewExitValue(CodeCantCreate, "Cannot create dir %s: %s", dirName, err)
		}
	}
	dir, err := parseBaseDir(cfg.withDirArg(dirName))
	if err != nil {
		return err
	}
	if _, src := dir.Config.lookup("schema"); src != nil {
		if _, isFile := src.(*File); isFile {
			return NewExitValue(CodeBadConfig, "Cannot use dir %s: an ancestor option file defines schema option", dir.Path)
		}
	}
	insts, err := dir.Instances()
	if err != nil {
		return err
	}
	if len(insts) == 0 {
		return NewExitValue(CodeBadConfig, "Command line did not specify which database server to connect to")
	}
	var lastErr error
	for _, inst := range insts {
		if lastErr = inst.Connect(); lastErr == nil {
			break
		}
	}
	if lastErr != nil {
		if len(insts) == 1 {
			return fmt.Errorf("Unable to connect to %s for %s: %s", insts[0], dir, lastErr)
		}
		return fmt.Errorf("Unable to connect to any of %d database servers for %s; last error %s", len(insts), dir, lastErr)
	}
	return fmt.Errorf("Unable to connect to %s for %s: %s", insts[0], dir, "unsupported server")
}
