var errInvalidConn = errors.New("invalid connection")

// mysqlHandshake performs a minimal read of the server's initial handshake
// packet, emulating driver error behavior for non-MySQL servers.
func mysqlHandshake(conn net.Conn, inst *Instance) error {
	conn.SetReadDeadline(time.Now().Add(20 * time.Second))
