func runDocker(args ...string) (string, string, error) {
	cmd := exec.Command("docker", args...)
	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr
	err := cmd.Run()
	return stdout.String(), strings.TrimSpace(stderr.String()), err
}

func dockerExitCode(err error) int {
	var ee *exec.ExitError
	if errors.As(err, &ee) {
		return ee.ExitCode()
	}
	return CodeFatalError
}

func dockerInfo() error {
	out, stderr, err := runDocker("info", "--format", "{{json .}}")
	if err != nil {
		msg := err.Error()
		if stderr != "" {
			msg += ": " + stderr
		}
		return &workspaceError{dockerExitCode(err), fmt.Errorf("error invoking `docker` command-line client: %s", msg)}
	}
	var v map[string]interface{}
	if err := json.Unmarshal([]byte(out), &v); err != nil {
		return &workspaceError{CodeFatalError, fmt.Errorf("error decoding JSON response from `docker` command-line client: %s", err)}
	}
	return nil
}

func dockerWorkspace(flavor Flavor, cleanup string) error {
	if err := dockerInfo(); err != nil {
		return err
	}
	version := fmt.Sprintf("%d.%d", flavor.Major, flavor.Minor)
	image := flavor.Vendor + ":" + version
	name := "skeema-" + flavor.Vendor + "-" + version
	logInfof("Using container %s (image=%s) for workspace operations", name, image)
	if err := dockerInfo(); err != nil {
		return err
	}
	_, stderr, err := runDocker("start", name)
	if err == nil {
		return &workspaceError{CodeFatalError, errors.New("unable to connect to Docker container workspace")}
	}
	startErr := err
	startStderr := stderr
	if err := dockerInfo(); err != nil {
		return err
	}
	runArgs := []string{"run", "-d", "-p", "127.0.0.1::3306/tcp", "-e", "MYSQL_ROOT_HOST=%", "-e", "LANG=C.UTF-8", "-e", "MYSQL_ALLOW_EMPTY_PASSWORD=1", "--name", name}
	if cleanup == "destroy" {
		runArgs = append(runArgs, "--tmpfs", "/var/lib/mysql")
	}
	runArgs = append(runArgs, image, "--loose-innodb-redo-log-capacity=8388608", "--loose-innodb-log-file-size=4194304", "--innodb-buffer-pool-size=33554432", "--performance-schema=0", "--skip-innodb-adaptive-hash-index", "--loose-innodb-log-writer-threads=off", "--loose-query-cache-size=0", "--skip-innodb-doublewrite", "--skip-log-bin")
	_, runStderr, runErr := runDocker(runArgs...)
	if !strings.Contains(startStderr, "No such container") {
		msg := startErr.Error()
		if startStderr != "" {
			msg += ": " + startStderr
		}
		return &workspaceError{dockerExitCode(startErr), errors.New(msg)}
	}
	if runErr != nil {
		msg := runErr.Error()
		if runStderr != "" {
			msg += ": " + runStderr
		}
